INSERT INTO "public"."cards" ("id", "num", "title", "difficulty", "tags", "key_points", "complexity", "follow_ups", "gotchas", "created_at", "last_reviewed", "description", "example", "stumbles", "completion_count") VALUES
	(28, 560, 'Subarray Sum Equals K', 'medium', '{array,hash-table,prefix-sum}', '["Prefix sum + HashMap：對每個 prefix_sum 查 prefix_sum - k 在 map 裡幾次", "seen = {0: 1} 初始化 — 讓從頭開始的 subarray 也能配對", "HashMap 存「次數」不是 True/False — 同 prefix_sum 會重複出現", "先 count += seen.get(prefix_sum - k, 0) 再登記自己進 map", "結構跟 Two Sum 一致：查 complement → 登記自己"]', 'O(n) time, O(n) space', '["能用 sliding window 嗎？— 不行，nums 可能有負數，sum 不單調", "如果要回傳起訖 index？— seen 存 index 而非次數，subarray = nums[seen_index+1 : i+1]", "同模式變體 — https://leetcode.com/problems/subarray-sums-divisible-by-k/"]', '["忘記 seen = {0: 1} — 從頭開始、總和剛好 k 的 subarray 會漏掉", "存 True/False 而非 count — 有負數時同 prefix_sum 重複出現會少算", "Brute force sum(nums[i:j]) 是 O(n³) 不是 O(n²) — 每次 sum 又是 O(n)"]', '2026-04-16 11:53:02.007811+00', '2026-05-10 15:13:52.513+00', 'Given an array of integers nums and an integer k, return the total number of contiguous subarrays whose sum equals k.', 'Input: nums = [1,2,3], k = 3
Output: 2', '["sum_counts[x]=2 是兩個合法起點 candidates，不是 double-count — 加進 map 不是加進 count", "Map entry 不會被『用掉』— 同個起點可配多個未來終點，每對都算一個合法 subarray"]', 2),
	(24, 706, 'Design HashMap', 'easy', '{hash-table,design,array,linked-list}', '["固定大小 array + hash function（key % size）", "Chaining 處理 collision：每個 bucket 存 list of (key, value) tuples", "Size 選質數（如 1009）讓 mod 分布更均勻", "put/get/remove 都是遍歷 bucket 比對 key"]', 'Average O(1), worst O(n) per op', '["為什麼 size 選質數？— 減少 mod 碰撞，分布更均勻", "什麼是 load factor？— 元素數 / bucket 數，> 0.75 就 resize + rehash", "Chaining vs open addressing？— chaining 串 list，open addressing 找下一個空位"]', '["不能用 Python dict 包一層 — dict 本身就是 hashmap", "get / remove 要處理 key 不存在的 edge case", "遍歷 bucket 比對 key，不是把 key 當 bucket 內的 index"]', '2026-04-16 11:49:22.976844+00', '2026-05-11 07:08:49.4+00', 'Design a HashMap without using any built-in hash table libraries. Support put(key, value), get(key) returning -1 if absent, and remove(key).', 'Input:
["MyHashMap","put","put","get","get","put","get","remove","get"]
[[],[1,1],[2,2],[1],[3],[2,1],[2],[2],[2]]
Output:
[null,null,null,1,-1,null,1,null,-1]', '[]', 2),
	(34, 3, 'Longest Substring Without Repeating Characters', 'medium', '{string,hash-table,sliding-window}', '["Sliding window + HashMap of char → last seen index", "碰到重複時 left = char_index[c] + 1，O(1) 跳轉", "不用清 map — 只覆蓋值，靠 index >= left 判斷是否還在 window", "每步更新 max_len，不要存整串歷史長度"]', 'O(n) time, O(min(n, m)) space where m is charset size', '["為什麼用 dict 不用 set？— dict 存 index 可以 O(1) 跳 left，set 只能一格一格縮", "為什麼條件要 char_index[c] >= left？— 舊 index 可能已在 window 外，忽略它"]', '["空 window 長度是 0，別用 [1] 初始化 max_len — 會整路多 1", "別假設只有 26 個字母 — 題目包含 digits、symbols、spaces", "找到重複時別忘了同時更新該 char 的 index 到 right"]', '2026-04-16 11:56:48.671342+00', '2026-05-11 07:45:56.827+00', 'Given a string s, find the length of the longest substring without repeating characters.', 'Input: s = "abcabcbb"
Output: 3', '[]', 2),
	(35, 8, 'String to Integer (atoi)', 'medium', '{string,math}', '["lstrip 後逐字元用 index 遍歷 — 不要用 split()", "Sign 只看第一個非空白字元，之後 i+=1", "result = result * 10 + int(s[i]) 累加到非 digit 為止", "最後 max(-2**31, min(result, 2**31 - 1)) 一行 clamp"]', 'O(n) time, O(1) space', '["Leading zeros 為什麼不用特別處理？— 0*10+0=0，累加法天然跳過", "為什麼不能用 split()？— split 按空白切成 words，\"-42\" 變成 [\"-42\"] 整塊不是逐字元"]', '["split() 切的是 words 不是 chars — atoi 要逐字元", "Sign 只認一個 — \"+-12\" 要 return 0", "空字串或 lstrip 後為空要 return 0", "記得 clamp，不要讓結果超出 [-2^31, 2^31 - 1]"]', '2026-04-16 11:58:09.049437+00', '2026-05-04 13:59:45.048+00', 'Convert a string to a 32-bit signed integer. Skip leading whitespace, read optional sign, consume digits until non-digit, and clamp to int32 range.', 'Input: s = "   -42"
Output: -42', '[]', 2),
	(32, 383, 'Ransom Note', 'easy', '{hash-table,string,counting}', '["Iterate Counter.items() 不是原字串 — 重複字母才不會重複掃", "Counter[missing_key] 回傳 0 不是 KeyError — 不用先檢查存在性", "Pythonic: Counter(ransomNote) <= Counter(magazine) 就是 multiset subset", "更短: not (Counter(ransomNote) - Counter(magazine))，減法只保留正數", "Early exit: len(ransomNote) > len(magazine) 直接 return False"]', 'O(n+m) time, O(1) space (lowercase English, alphabet bounded by 26)', '["字符集是 Unicode 不是 lowercase？— space 變成 O(k) where k = unique chars", "這 pattern 延伸到哪？— Valid Anagram、Group Anagrams、Minimum Window Substring", "下一題試 Valid Anagram — https://leetcode.com/problems/valid-anagram/"]', '["方向別搞反 — magazine 要能 cover ransomNote，不是反過來"]', '2026-04-16 11:55:44.332059+00', '2026-05-10 09:51:49.313+00', 'Given two strings ransomNote and magazine, return true if ransomNote can be constructed using letters from magazine. Each letter in magazine can only be used once.', 'Input: ransomNote = "aa", magazine = "aab"
Output: true', '["別寫 if letter not in mag_counter — Counter 的 missing key 回傳 0，那行是多餘的", "Loop 的是 note_counter.items() 不是 ransomNote 字串 — 不然 ''aaaaa'' 會重複檢查 ''a'' 五次", "Lowercase-only 題目 space 是 O(1) 不是 O(n) — alphabet 有上限要講清楚"]', 2),
	(30, 128, 'Longest Consecutive Sequence', 'medium', '{array,hash-table,union-find}', '["把 nums 丟進 HashSet，O(1) lookup 是關鍵", "只從「起點」往上數 — num-1 不在 set 才算起點", "從起點跑 while num+1 in set，邊走邊累加 streak", "非起點直接 skip，避免從序列中間重複展開"]', 'O(n) time, O(n) space', '["為什麼總體是 O(n) 而非 O(n²)？— 每個數最多被內層 while 訪問一次，只有起點才觸發展開，攤銷 2n", "如果要回傳序列本身不只是長度？— 記錄起點和長度即可重建"]', '["while 迴圈查的是 set 不是原 list — 查 list 的 in 是 O(n)，會打回 O(n²)", "先判斷 num-1 not in set 再展開，否則每段序列會被算多次", "不需要額外 dict 存每個起點的長度，一個 longest 變數就夠"]', '2026-04-16 11:54:36.268201+00', '2026-05-09 04:16:16.169+00', 'Given an unsorted array of integers, return the length of the longest consecutive elements sequence in O(n) time.', 'Input: nums = [100,4,200,1,3,2]
Output: 4
Explanation: The longest consecutive sequence is [1,2,3,4]', '["外層 for 要 iterate num_set 不是 nums — 有 duplicate 時每個重複起點都會重跑整段序列，退化成 O(n²) TLE"]', 2),
	(36, 394, 'Decode String', 'medium', '{string,stack,recursion}', '["Stack 存 (prev_str, num) — [ 是暫存先不算，] 是現在可以算", "維護 current_str 和 current_num 兩個變數往前掃", "遇到 [ push 然後 reset，遇到 ] pop 出來做 prev + current × num", "數字可能多位：current_num = current_num × 10 + int(ch)", "嵌套天然從內往外解 — LIFO 就是「最內層最先 close」"]', 'O(S) time, O(S) space，S = 輸出長度', '["為什麼不是 O(n)？— 字串複製成本跟輸出長度成正比，不是輸入長度", "能不能用 recursion？— 可以，遇到 [ 遞迴下去解完子字串再回來", "類似 pattern 還有哪些？— Basic Calculator、nested list parsing，嵌套求值都是 stack"]', '["數字要累加不能直接 int(ch) — 輸入可能有 100[a] 這種多位數", "push 之後要記得 reset current_str 和 current_num 為空", "pop 出來是 prev_str + current_str × num，順序別寫反", "像 2[abc]3[cd]ef 裡沒被 bracket 包的 ef 會自然累積到最後的 current_str，不用特別處理"]', '2026-04-16 11:58:47.847011+00', NULL, 'Given an encoded string of form k[encoded_string], return its decoded string. Brackets can be nested and k is a positive integer (may be multi-digit).', 'Input: s = "3[a2[c]]"
Output: "accaccacc"', '[]', 0),
	(59, 215, 'Kth Largest Element in an Array', 'medium', '{array,heap,divide-and-conquer,sorting,quickselect}', '["heapq.nlargest(k, nums)[-1] — 一行解，O(n log k) time O(k) space", "nlargest 內部自己建 size-k min-heap，不需要先 heapify", "最佳解是 quickselect — quicksort 的懶人版，只 recurse 有 target 的那一邊", "Quickselect 平均 O(n)，worst O(n²) 用 random pivot 緩解", "kth largest = (n-k)th smallest in 0-indexed sorted order"]', 'Heap: O(n log k) time, O(k) space. Quickselect: O(n) average, O(n²) worst, O(1) extra space', '["k 接近 n 時怎辦？— 直接 sorted(nums)[-k]，O(n log n) 反而更乾淨", "怎麼避免 quickselect 的 O(n²) worst case？— Random pivot，或 median-of-medians 保證 O(n)", "Streaming 版本（資料一直進來）試試 — https://leetcode.com/problems/kth-largest-element-in-a-stream/"]', '["heapq 是 min-heap，要拿 largest 得用 nlargest 或存負值", "Quickselect 的 partition 要小心 pivot 的最終位置，recurse 時要排除 pivot 本身"]', '2026-04-24 14:25:42.110714+00', '2026-05-10 13:47:51.584+00', 'Given an integer array nums and an integer k, return the kth largest element in the array (kth largest in sorted order, not the kth distinct element).', 'Input: nums = [3,2,1,5,6,4], k = 2
Output: 5', '["別在 nlargest 前面多寫一個 heapify — 完全沒用，還多 O(n) 又 mutate input", "Complexity 分析要對齊實際寫的 code — 上次嘴巴說 O(n log k) 手卻寫了 O(n) 的 heapify，前後不一致", "面試時要主動 walk through trade-off space：sort / heap / quickselect 三種都提，不要只給一個解就停"]', 0),
	(40, 226, 'Invert Binary Tree', 'easy', '{tree,bfs,dfs,recursion}', '["遞迴：root.left, root.right = invert(right), invert(left) 然後 return root", "Tuple swap RHS 整個算完才 assign — 拆兩行會 bug", "迭代版骨架：pop → swap → 推非 None 子節點，三步驟", "queue (deque) = BFS，stack (list) = DFS — 換容器就換遍歷方式", "BFS 用 deque.popleft 才是 O(1)"]', 'O(n) time, O(n) space worst case', '["BFS vs DFS 空間差異？— 平衡樹 DFS 只要 O(log n)，BFS 最後一層就 O(n/2)", "怎麼把 BFS 改成 iterative DFS？— queue 換成 stack，popleft 換成 pop，其他不變", "遞迴 vs 迭代 trade-off？— 遞迴乾淨但 skewed tree 會 stack overflow，迭代可控"]', '["Tuple swap 不能拆成兩行 — 第二行會用到已被覆蓋的 root.right", "別用 list.pop(0) 當 queue — 是 O(n)，整體變 O(n²)", "空間複雜度要連 BFS queue / DFS stack 一起算，不是只有 output"]', '2026-04-16 12:02:10.948175+00', '2026-05-11 07:23:33.287+00', 'Given the root of a binary tree, invert it (mirror left and right at every node) and return the root.', 'Input: root = [4,2,7,1,3,6,9]
Output: [4,7,2,9,6,3,1]', '["每個解法都要附 time / space complexity — 上次 iterative 版漏了，recursive 有寫", "Tuple swap 慣例 left 先 right 後：root.left, root.right = invert(right), invert(left)", "BFS 不會自動比遞迴省空間 — 平衡樹 BFS 是 O(n)，要省空間改 DFS stack"]', 2),
	(41, 98, 'Validate Binary Search Tree', 'medium', '{tree,bst,dfs,bfs,recursion}', '["每個節點帶 (lo, hi) 開區間，整個子樹都要落在區間內", "往左走：hi 收緊成 node.val；往右走：lo 收緊成 node.val", "DFS 把 (lo, hi) 走 args；BFS 塞進 queue tuple", "檢查用嚴格不等式 lo < node.val < hi", "Plan B：BST 的 inorder 遍歷必定嚴格遞增"]', 'O(n) time. DFS space O(h); BFS space O(n) worst case', '["還有什麼解法？— Inorder 遍歷檢查嚴格遞增，BST inorder 必定排序", "為什麼不能只跟 parent 比？— 孫節點可能違反祖父約束，如 [5,1,6,null,null,3,7]", "下一題練 BST inorder — https://leetcode.com/problems/kth-smallest-element-in-a-bst/"]', '["[1,1] 必須回傳 false — 用嚴格 < 不是 <=", "左右子都要同時受 lo 和 hi 兩邊約束，單邊檢查會漏", "Inorder 解法的 prev 要用 nonlocal 或包成 list — 不然 Python 會當成新的 local"]', '2026-04-16 12:02:48.296169+00', '2026-05-08 13:27:31.273+00', 'Given the root of a binary tree, determine if it is a valid BST where every node in the left subtree is strictly less than the node and every node in the right subtree is strictly greater.', 'Input: root = [5,1,6,null,null,3,7]
Output: false', '["更新 (lo, hi) 後要塞回 queue 帶下去 — 不能只在比較時寫對就忘了 enqueue", "BFS 的 space 不是 O(1) 是 O(n) worst case — queue 最寬一層 ~n/2 個 node", "樹題先想 DFS recursion，bounds 當 args 傳；別卡在 BFS 想不出 recursion 結構"]', 2),
	(25, 242, 'Valid Anagram', 'easy', '{hash-table,string,sorting}', '["Counter(s) == Counter(t) 一行解決", "Fixed 26-array 是 O(1) space 但只支援 lowercase a-z", "Counter 用 O(k) space 換來任意 alphabet 支援", "len(s) != len(t) 可早 return 加速"]', 'O(n) time, O(n) space', '["Unicode 怎辦？— Counter 本身就 OK，26-array 解法才壞掉", "café 兩種編碼怎比？— 先 unicodedata.normalize(''NFC'', s) 再丟 Counter", "Group Anagrams 是進階版 — https://leetcode.com/problems/group-anagrams/"]', '["26-array 解的 ord(c) - ord(''a'') 遇到非 ASCII 會 IndexError 或裝錯 bucket", "Counter 數 code points 不是 grapheme — 🇹🇼 (兩個 regional indicator) 會被當兩個字"]', '2026-04-16 11:50:43.510321+00', '2026-04-25 17:15:38.11+00', 'Given two strings s and t, return true if t is an anagram of s. Each character must appear the same number of times in both.', 'Input: s = "anagram", t = "nagaram"
Output: true', '["Counter 解已經 Unicode-safe — follow-up 是給用 26-array 的人問的，不用改 code", "café 在 NFC vs NFD 下可能是 4 或 5 個 code points — 比較前先 normalize"]', 2),
	(42, 102, 'Binary Tree Level Order Traversal', 'medium', '{tree,bfs,breadth-first-search}', '["BFS 骨架：while queue 外層走 level，內層走 current level 的 nodes", "用 for _ in range(len(queue)) 凍結當前層大小，popleft 一次搞定", "drain level 時同步 append node.val 到 level_list — 別先 snapshot 再 drain", "加入 children 前先 check None，別污染 queue", "對稱結構：每次迭代收集當前層，不要把 root 特判在外"]', 'O(n) time, O(n) space — space 上界是最寬那層 (最壞 n/2)，不是樹高', '["Zigzag 版本？— 遍歷順序不變，只在組 level_list 時用 deque.appendleft 或最後 reverse，https://leetcode.com/problems/binary-tree-zigzag-level-order-traversal/", "Bottom-up 版本？— 同骨架，最後 result[::-1] 或 result.reverse()，https://leetcode.com/problems/binary-tree-level-order-traversal-ii/", "遞迴 DFS 版？— helper(node, level)，用 len(levels) == level 判斷該層是否已建立", "BFS vs DFS 空間？— BFS 最壞 O(n/2) 在最後一層，DFS 最壞 O(h) 在 recursion stack"]', '["別把 root 在迴圈外特殊處理 — 會讓邏輯不對稱並需要 if level_list guard", "for node in queue 同時 append 會 invalidate iterator — 要用 for _ in range(size) 配 popleft"]', '2026-04-17 13:03:47.609219+00', '2026-04-24 15:46:37.839+00', 'Given the root of a binary tree, return the level order traversal of its nodes'' values as a list of lists, one sublist per level from top to bottom.', 'Input: root = [3,9,20,null,null,15,7]
Output: [[3],[9,20],[15,7]]', '["又用 list.pop(0) 了 — #226 已經被提醒過是 O(n) 害整體變 O(n²)，下次直接 from collections import deque 配 popleft", "snapshot 層的值時別 walk 兩次 — result.append([n.val for n in queue]) 再 drain 是 double work，drain 時同步收 val 就好", "複雜度別說『O(n) 更精確是 O(2n)』— big O 定義就是丟常數，講『each node O(1) work, total O(n)』才對"]', 2),
	(27, 347, 'Top K Frequent Elements', 'medium', '{array,hash-table,heap,bucket-sort,sorting}', '["三種解法：sorting O(n log n)、min-heap of size k O(n log k)、bucket sort O(n)", "Bucket sort 關鍵：frequency 上限是 len(nums)，所以 frequency 可以當 index", "Min-heap of size k 是 bouncer 演算法 — root 是現任最弱的，新人比他強才換掉", "nlargest 內部就維護 size-k min-heap，input 不需要先 heapify", "Heapify 是 O(n) 不是 O(n log n) — Floyd''s algorithm bottom-up sift down"]', 'Bucket sort O(n); min-heap-of-k O(n log k) time O(k) space; max-heap-of-all O(n + k log n) time O(n) space', '["為什麼找最大 k 個用 min-heap？— root 是當前第 k 大的守門員，新元素比它大才替換", "Min-heap-of-k 真的比 max-heap-of-all 快嗎？— 時間其實常常更慢，贏在 O(k) space 跟 streaming 相容", "下一題試 H-Index — https://leetcode.com/problems/h-index/"]', '["Buckets 長度要 len(nums) + 1，因為 frequency 最大可能等於 len(nums)", "Python heapq 只有 min-heap，要 max-heap 得把 key negate", "Bucket sort 是 O(n) 因為 frequencies 有界 — 一般 sort by 任意 key 沒這個保證"]', '2026-04-16 11:52:17.528054+00', '2026-05-10 13:57:07.779+00', 'Given an integer array nums and an integer k, return the k most frequent elements in any order.', 'Input: nums = [1,1,1,2,2,3], k = 2
Output: [1,2]', '["heapq.nlargest 內部已維護 size-k min-heap — 不要再先 heapify input，那是多餘的 O(n) 工", "Max-heap-of-all 是 O(n + k log n) 不是 O(k log n) — heapify 那個 O(n) 不能省", "Min-heap-of-k 選的真正理由是 O(k) space 跟 streaming — 時間反而常常輸給 max-heap-of-all", "Bucket sort 收齊就 break 並最後 results[:k] — 只用 if len < k 空跑會錯，最後一 bucket 可能把總數推過 k"]', 2),
	(31, 290, 'Word Pattern', 'easy', '{hash-table,string}', '["Bijection 要雙向 check — char→word 和 word→char 兩個 map", "邊 zip 邊 check conflict，不能 build 完再比 length", "用 zip(pattern, words) 取代 range(len(...))，更 Pythonic", "一行精簡版：len(set(zip)) == len(set(pattern)) == len(set(words))", "setdefault(k,v) 可把 conflict check 收一行 — readability 換 cleverness"]', 'O(N) time/space, N = len(s) — string hash 是 O(k)', '["為什麼要先檢查長度？— zip 會截斷到較短的那個，造成 false positive", "為什麼需要雙向 map？— 只做單向會漏掉兩個 char 對到同一個 word 的情況", "下一題試 Isomorphic Strings — https://leetcode.com/problems/isomorphic-strings/"]', '["zip 會 silently truncate — 長度不等時一定要先 return False", "只檢查單向 map 不夠 — pattern=\"ab\", s=\"dog dog\" 會誤判成 true", "set(zip(...)) 技巧依賴長度相等前提，少了 guard 會出 bug"]', '2026-04-16 11:55:05.169277+00', '2026-05-11 07:20:18.597+00', 'Given a pattern and a string s, return true if s follows the same pattern — meaning there is a bijection between letters in pattern and words in s.', 'Input: pattern = "abba", s = "dog cat cat dog"
